/* All layers retain original scene coordinates; only the world camera moves. */
(()=>{
const c=window.GARAGE_CONFIG,$=id=>document.getElementById(id),stage=$('garage-stage'),world=$('garage-world'),label=$('garage-label');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const layers=c.objects;const objects=layers.filter(o=>o.interactive!==false).sort((a,b)=>a.pivot[0]-b.pivot[0]);
let focused=objects.findIndex(o=>o.id===c.initial),selected=null,ready=false,mouse=0,last=0,camera={scale:0,x:0,y:0},lockedUntil=0;
const rendered=new Map(),menus=new Map(),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
$('garage-back').textContent=c.text.back;$('garage-reset').textContent=c.text.reset;$('garage-help').textContent=c.text.help;$('garage-select').textContent=c.text.select;$('garage-prev').setAttribute('aria-label',c.text.previous);$('garage-next').setAttribute('aria-label',c.text.next);$('garage-loading').textContent=c.text.loading;
world.style.width=c.width+'px';world.style.height=c.height+'px';world.style.setProperty('--pulse-seconds',c.motion.pulseSeconds+'s');world.style.setProperty('--pulse-scale',c.motion.pulseScale);
function load(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=src;});}
function setFocus(index){if(!ready||selected!==null)return;focused=(index+objects.length)%objects.length;for(const o of objects)rendered.get(o.id).element.classList.toggle('focused',o===objects[focused]);label.textContent=objects[focused].name;label.hidden=false;}
function choose(){if(!ready||selected!==null||performance.now()<lockedUntil)return;selected=objects[focused];mouse=0;lockedUntil=performance.now()+(reduced?0:380);label.hidden=true;menus.get(selected.id).hidden=false;menus.get(selected.id).querySelector('button').focus();controls();}
function close(){if(selected===null)return;menus.get(selected.id).hidden=true;selected=null;mouse=0;lockedUntil=performance.now()+(reduced?0:380);label.hidden=false;controls();$('garage-select').focus();}
function controls(){for(const id of ['garage-prev','garage-next','garage-select'])$(id).disabled=!ready||selected!==null;}
function reset(){for(const menu of menus.values())menu.hidden=true;selected=null;mouse=0;lockedUntil=0;focused=objects.findIndex(o=>o.id===c.initial);setFocus(focused);controls();}
for(const o of objects){const menu=document.createElement('section');menu.className='garage-menu';menu.id=o.menu.id;menu.hidden=true;menu.setAttribute('role','dialog');menu.setAttribute('aria-labelledby',o.menu.id+'-title');const bar=document.createElement('div');bar.className='garage-menu-title';const heading=document.createElement('h2');heading.id=o.menu.id+'-title';heading.textContent=o.name;const button=document.createElement('button');button.textContent=c.text.close;button.onclick=close;bar.append(heading,button);const content=document.createElement('div');content.className='garage-menu-content';for(const line of o.menu.content){const p=document.createElement('p');p.textContent=line;content.append(p);}menu.append(bar,content);$('garage-menus').append(menu);menus.set(o.id,menu);}
Promise.all([load(c.background),...layers.map(o=>load('assets/garage/'+o.src))]).then(images=>{
 $('garage-background').src=images[0].src;
 layers.forEach((o,index)=>{const [x,y,w,h]=o.bounds,element=document.createElement('div'),canvas=document.createElement('canvas');element.className='garage-object';element.dataset.object=o.id;element.style.cssText=`left:${x}px;top:${y}px;width:${w}px;height:${h}px;z-index:${o.layer};--pivot:${o.pivot[0]-x}px ${o.pivot[1]-y}px`;canvas.width=w;canvas.height=h;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(images[index+1],x,y,w,h,0,0,w,h);const alpha=context.getImageData(0,0,w,h).data;let halo=null;if(o.interactive!==false){halo=document.createElement('canvas');halo.className='garage-halo';halo.width=w;halo.height=h;halo.getContext('2d').drawImage(canvas,0,0);element.append(halo);}element.append(canvas);world.append(element);rendered.set(o.id,{element,alpha,halo,weight:0,scale:1});});
 ready=true;$('garage-loading').hidden=true;reset();
}).catch(()=>{$('garage-loading').textContent=c.text.error;});controls();
function target(){const w=stage.clientWidth,h=stage.clientHeight,base=Math.max(w/c.width,h/c.height)*c.motion.overscan;const o=selected||objects[focused];let scale=base;
 if(selected){const availableHeight=h-40;scale=Math.max(base,Math.min(base*o.zoom.scale,availableHeight/o.bounds[3]*.9,w/o.bounds[2]*.85));}
 const visibleWidth=w/scale;const explorationX=w<681?o.pivot[0]:clamp(c.width/2,o.bounds[0]+o.bounds[2]-visibleWidth/2+40,o.bounds[0]+visibleWidth/2-40);const center=selected?o.zoom.target:[explorationX,c.height/2];let x=w/2-center[0]*scale-(selected||reduced?0:mouse*c.motion.mouseTravel),y=h*.5-center[1]*scale;
 // Clamp to the painted background so pan/zoom never reveal unpainted edges.
 x=clamp(x,w-c.width*scale,0);y=clamp(y,h-c.height*scale,0);return{scale,x,y};}
function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;const t=target(),ease=reduced||!camera.scale?1:1-Math.exp(-dt*(selected?c.motion.zoomSmoothing:c.motion.smoothing));for(const key of ['scale','x','y'])camera[key]+=(t[key]-camera[key])*ease;world.style.transform=`translate(${camera.x}px,${camera.y}px) scale(${camera.scale})`;if(ready){const wave=(1-Math.cos(now*2*Math.PI/(c.motion.pulseSeconds*1000)))/2;for(const o of objects){const r=rendered.get(o.id),active=o===objects[focused]?1:0;r.weight+=(active-r.weight)*(reduced?1:1-Math.exp(-dt*12));r.scale=reduced?1:1+r.weight*wave*((o.pulseScale??c.motion.pulseScale)-1);r.element.style.transform=`scale(${r.scale})`;r.halo.style.opacity=r.weight;}}if(ready&&!selected){const o=objects[focused];let x=camera.x+o.pivot[0]*camera.scale,y=camera.y+o.bounds[1]*camera.scale-40;x=clamp(x-label.offsetWidth/2,10,stage.clientWidth-label.offsetWidth-10);y=clamp(y,10,stage.clientHeight-45);label.style.left=x+'px';label.style.top=y+'px';}requestAnimationFrame(frame);}requestAnimationFrame(frame);
stage.addEventListener('pointermove',e=>{if(!selected)mouse=clamp((e.clientX-stage.getBoundingClientRect().left)/stage.clientWidth*2-1,-1,1);});stage.addEventListener('pointerleave',()=>mouse=0);
stage.addEventListener('click',e=>{if(!ready||selected||e.target.closest('.garage-menu'))return;const box=stage.getBoundingClientRect(),x=(e.clientX-box.left-camera.x)/camera.scale,y=(e.clientY-box.top-camera.y)/camera.scale;for(const o of [...objects].sort((a,b)=>b.layer-a.layer)){const [bx,by,w,h]=o.bounds,px=Math.floor((x-o.pivot[0])/rendered.get(o.id).scale+o.pivot[0]-bx),py=Math.floor((y-o.pivot[1])/rendered.get(o.id).scale+o.pivot[1]-by);if(px>=0&&px<w&&py>=0&&py<h&&rendered.get(o.id).alpha[(py*w+px)*4+3]>c.motion.alphaThreshold){setFocus(objects.indexOf(o));break;}}});
$('garage-prev').onclick=()=>setFocus(focused-1);$('garage-next').onclick=()=>setFocus(focused+1);$('garage-select').onclick=choose;$('garage-reset').onclick=reset;
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='Escape'){e.preventDefault();close();return;}if(selected)return;if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a'){e.preventDefault();setFocus(focused-1);}else if(e.key==='ArrowRight'||e.key.toLowerCase()==='d'){e.preventDefault();setFocus(focused+1);}else if(e.key==='Enter'&&!e.target.closest('.prototype-header')){e.preventDefault();choose();}});
})();
